void lbVector_Mirror(Vec3* a, Vec3* unit_mirror_axis)
{
    float f =
        (unit_mirror_axis->x * a->x + unit_mirror_axis->y * a->y) * -2.0f;

    a->x += unit_mirror_axis->x * f;
    a->y += unit_mirror_axis->y * f;
}

