void lbVector_Mirror(Vec3* a, Vec3* unit_mirror_axis)
{
    float y_product = unit_mirror_axis->y * a->y;
    float f = PF_SlippiMulAddF32(unit_mirror_axis->x, a->x, y_product) * -2.0f;

    a->x = PF_SlippiMulAddF32(unit_mirror_axis->x, f, a->x);
    a->y = PF_SlippiMulAddF32(unit_mirror_axis->y, f, a->y);
}

